const negotiationLane = H.lane('negotiations', negotiation)
  .handler(negotiationRound, { retries: 2, backoff: { first: { minutes: 10 }, factor: 2 }, exhausted: 'negotiation-stalled' })
  .suppliers(H.operator, vendorReplies)
