    message: z.string(),
    customerEmail: z.string(),
    slaDue: z.string(),
  }),
  read: body =>
    body.event === 'created'
      ? {
          create: { subject: body.subject, latestMessage: body.message, customerEmail: body.customerEmail, slaDue: body.slaDue },
          key: body.conversationId,
        }
