  if (value === undefined) return undefined;
  const approvals = ctx.metrics.rate(approvalRate, { facets: [category.of(value)] });
  const audits = ctx.metrics.total(auditsOpened, { facets: [category.of(value)], window: { calendar: 'month' } });
