    round =>
      round
        .step('draft', drafter, ctx => ({
          task: `Draft the ${ctx.unit.attributes.category} contract with ${ctx.unit.attributes.counterparty}, applying redlines:\n${ctx.unit.attributes.redlines.join('\n')}`,
