    if (!database.success || Number.isNaN(number)) return to.skip();
    return to.create({
      key: migrationKey(database.data, number),
      number,
      database: database.data,
      file: f.path,
      previous: number > 1 ? migrationKey(database.data, number - 1) : undefined,
